const r=document.querySelectorAll(".toc-item"),n=document.querySelectorAll("h2, h3");function l(){let t="";n.forEach(e=>{e.getBoundingClientRect().top<=100&&(t=e.id)}),r.forEach(e=>{e.getAttribute("href")===`#${t}`?e.classList.add("active"):e.classList.remove("active")})}window.addEventListener("scroll",l);document.querySelectorAll(".toc-item").forEach(t=>{t.addEventListener("click",e=>{e.preventDefault();const c=t.getAttribute("href").slice(1),o=document.getElementById(c);o&&o.scrollIntoView({behavior:"smooth"})})});
